  udp: false

proxy-groups:
- name: 负载均衡
  type: load-balance
  url: https://www.gstatic.com/generate_204
  interval: 300
  strategy: round-robin
  proxies:
    - vless-reality-vision-$hostname
    - hysteria2-$hostname

- name: 自动选择
  type: url-test
  url: https://www.gstatic.com/generate_204
  interval: 300
  tolerance: 50
  proxies:
    - vless-reality-vision-$hostname
    - hysteria2-$hostname

- name: 🌍选择代理节点
  type: select
  proxies:
    - 负载均衡
    - 自动选择
    - DIRECT
    - vless-reality-vision-$hostname
    - hysteria2-$hostname
    - socks5-$hostname

rules:
  - GEOIP,LAN,DIRECT
  - GEOSITE,CN,DIRECT
  - GEOIP,CN,DIRECT
  - MATCH,🌍选择代理节点
EOF
  then
    rm -f "$sbox_candidate" "$clash_candidate"
    return 1
  fi
  chmod 600 "$sbox_candidate" "$clash_candidate" || { rm -f "$sbox_candidate" "$clash_candidate"; return 1; }
  mv -f "$sbox_candidate" "$SB_DIR/sbox.json" || { rm -f "$sbox_candidate" "$clash_candidate"; return 1; }
  mv -f "$clash_candidate" "$SB_DIR/clash.yaml" || { rm -f "$clash_candidate"; return 1; }
}

sbshare(){
  local aggregate_tmp vl_tmp hy2_tmp socks_tmp
  vl_tmp=$(mktemp "$SB_DIR/.vl_reality.XXXXXX") || return 1
  hy2_tmp=$(mktemp "$SB_DIR/.hy2.XXXXXX") || { rm -f "$vl_tmp"; return 1; }
  socks_tmp=$(mktemp "$SB_DIR/.socks5.XXXXXX") || { rm -f "$vl_tmp" "$hy2_tmp"; return 1; }
  if ! result || ! resvless "$vl_tmp" || ! reshy2 "$hy2_tmp" || ! ressocks5 "$socks_tmp"; then
    rm -f "$vl_tmp" "$hy2_tmp" "$socks_tmp"
    return 1
  fi
  aggregate_tmp=$(mktemp "$SB_DIR/.jhdy.XXXXXX") || {
    rm -f "$vl_tmp" "$hy2_tmp" "$socks_tmp"
    return 1
  }
  if ! { cat "$vl_tmp" && cat "$hy2_tmp" && cat "$socks_tmp"; } > "$aggregate_tmp"; then
    rm -f "$vl_tmp" "$hy2_tmp" "$socks_tmp" "$aggregate_tmp"
    return 1
  fi
  chmod 600 "$vl_tmp" "$hy2_tmp" "$socks_tmp" "$aggregate_tmp" || {
    rm -f "$vl_tmp" "$hy2_tmp" "$socks_tmp" "$aggregate_tmp"
    return 1
  }
  if ! sb_client; then
    rm -f "$vl_tmp" "$hy2_tmp" "$socks_tmp" "$aggregate_tmp"
    return 1
  fi
  mv -f "$vl_tmp" "$SB_DIR/vl_reality.txt" || { rm -f "$vl_tmp" "$hy2_tmp" "$socks_tmp" "$aggregate_tmp"; return 1; }
  mv -f "$hy2_tmp" "$SB_DIR/hy2.txt" || { rm -f "$hy2_tmp" "$socks_tmp" "$aggregate_tmp"; return 1; }
  mv -f "$socks_tmp" "$SB_DIR/socks5.txt" || { rm -f "$socks_tmp" "$aggregate_tmp"; return 1; }
  mv -f "$aggregate_tmp" "$SB_DIR/jhdy.txt" || { rm -f "$aggregate_tmp"; return 1; }
  cp -p "$SB_DIR/jhdy.txt" "$SB_DIR/jhsub.txt" || return 1
  v2sub=$(cat "$SB_DIR/jhdy.txt" 2>/dev/null) || return 1
  echo
  white "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
  red "🚀【 聚合节点 】节点信息如下：" && sleep 2
  echo
  echo "分享链接"
  echo -e "${yellow}$v2sub${plain}"
  white "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
  echo
}

# Switch IP priority for server outbound domain_strategy (like original sb.sh)
switch_ip_priority(){
  local current new choose candidate retry commit_status
  if ! sbactive; then
    readp "按回车返回主菜单..."
    return 1
  fi
  v4v6_refresh || true
  if ! current=$(jq -er '.outbounds[] | select(.type == "direct" and .tag == "direct") | .domain_strategy // "prefer_ipv4"' "$SB_CONFIG" 2>/dev/null); then
    red "读取当前IP优先级失败，配置未修改"
    readp "按回车返回主菜单..."
    return 1
  fi
  echo
  while true; do
    green "切换IP优先级 (控制VPS出站时IPv4/IPv6的偏好)"
    echo -e "当前: ${yellow}$current${plain}"
    echo
    [[ -n $v4 ]] && green "1：IPV4优先 (prefer_ipv4)"
    [[ -n $v6 ]] && green "2：IPV6优先 (prefer_ipv6)"
    [[ -n $v4 ]] && green "3：仅IPV4 (ipv4_only)"
    [[ -n $v6 ]] && green "4：仅IPV6 (ipv6_only)"
    green "0：返回主菜单"
    readp "请选择【0-4】：" choose || return 1
    case "$choose" in
      1|2|3|4)
        case "$choose" in
          1) new="prefer_ipv4";;
          2) new="prefer_ipv6";;
          3) new="ipv4_only";;
          4) new="ipv6_only";;
        esac
        if [[ "$new" =~ ipv4 && -z $v4 ]] || [[ "$new" =~ ipv6 && -z $v6 ]]; then
          red "当前VPS不存在对应的IP地址"
          continue
        fi
        if ! candidate=$(mktemp "$SB_DIR/.sb.json.XXXXXX"); then
          red "创建IP优先级候选配置失败，原配置未修改"
          readp "按回车重试，输入0返回主菜单：" retry || return 1
          [[ $retry == 0 ]] && return 1
          continue
        fi
        if ! jq --arg strategy "$new" '
          if ([.outbounds[] | select(.type == "direct" and .tag == "direct")] | length) != 1
          then error("direct outbound missing or duplicated")
          else (.outbounds[] | select(.type == "direct" and .tag == "direct") | .domain_strategy) = $strategy
          end
        ' "$SB_CONFIG" > "$candidate" || \
          ! jq -e --arg strategy "$new" '[.outbounds[] | select(.type == "direct" and .tag == "direct" and .domain_strategy == $strategy)] | length == 1' "$candidate" >/dev/null; then
          rm -f "$candidate"
          red "生成IP优先级候选配置失败，原配置未修改"
          readp "按回车重新输入，输入0返回主菜单：" retry || return 1
          [[ $retry == 0 ]] && return 1
          continue
        fi
        if commit_config "$candidate"; then
          refresh_share_files_after_change || true
          green "IP优先级修改成功：$new"
          readp "按回车返回主菜单..."
          return 0
        else
          commit_status=$?
        fi
        if [[ $commit_status -eq 2 ]]; then
          red "IP优先级修改失败且自动回滚失败，请先检查服务和备份配置"
          readp "按回车返回主菜单..."
          return 2
        fi
        red "IP优先级修改失败，原配置未修改或已恢复"
        readp "按回车重新输入，输入0返回主菜单：" retry || return 1
        [[ $retry == 0 ]] && return 1
        ;;
      ""|0) return 0 ;;
      *)
        red "请输入0-4中的有效选项"
        ;;
    esac
  done
}
# sb-module: 60-cron
# Manage only sb-owned crontab entries.
load_current_crontab(){
  local error_file error_text temp_base=$SB_DIR
  CURRENT_CRONTAB=
  [[ -d $temp_base ]] || temp_base=/tmp
  error_file=$(mktemp "$temp_base/.crontab-error.XXXXXX") || return 1
  if CURRENT_CRONTAB=$(crontab -l 2>"$error_file"); then
    rm -f "$error_file"
    return 0
  fi
  error_text=$(cat "$error_file" 2>/dev/null)
  rm -f "$error_file"
  if printf '%s\n' "$error_text" | grep -qi 'no crontab for'; then
    return 0
  fi
  if printf '%s\n' "$error_text" | grep -qi 'no such file or directory' && \
     [[ ! -e /var/spool/cron/crontabs/root && ! -e /var/spool/cron/root ]]; then
    return 0
  fi
  red "读取root crontab失败，拒绝覆盖现有定时任务"
  return 1
}

crontab_has_acme_entries(){
  local content=$1
  printf '%s\n' "$content" | grep -Fq "$ACME_CRON_MARKER" ||
    printf '%s\n' "$content" | grep -Fq "$ACME_BIN --cron" ||
    printf '%s\n' "$content" | grep -Fq "$SB_DIR/cert_renew.sh"
}

acme_renew_cron_entry(){
  printf '%s\n' "17 3,9,15,21 * * * HOME=$SB_DIR $ACME_BIN --cron --home $ACME_HOME --config-home $ACME_HOME > /dev/null 2>&1 $ACME_CRON_MARKER"
}

acme_renew_cron_is_current(){
  local content=$1 entry exact_count marker_count command_count
  entry=$(acme_renew_cron_entry)
  exact_count=$(printf '%s\n' "$content" | grep -Fxc -- "$entry" || true)
  marker_count=$(printf '%s\n' "$content" | grep -Fc -- "$ACME_CRON_MARKER" || true)
  command_count=$(printf '%s\n' "$content" | grep -Fc -- "$ACME_BIN --cron" || true)
  [[ $exact_count -eq 1 && $marker_count -eq 1 && $command_count -eq 1 ]] &&
    ! printf '%s\n' "$content" | grep -Fq "$SB_DIR/cert_renew.sh"
}

filter_acme_cron_entries(){
  grep -Fv "$ACME_CRON_MARKER" |
    grep -Fv "$ACME_BIN --cron" |
    grep -Fv "$SB_DIR/cert_renew.sh"
}

crontab_has_restart_entries(){
  local content=$1
  printf '%s\n' "$content" | grep -Fq "$RESTART_CRON_MARKER"
}

filter_restart_cron_entries(){
  grep -Fv "$RESTART_CRON_MARKER"
}

remove_acme_renew_cron(){
  local current filtered
  load_current_crontab || return 1
  current=$CURRENT_CRONTAB
  if ! crontab_has_acme_entries "$current"; then
    rm -f "$SB_DIR/cert_renew.sh" "$SB_DIR/.cert_mtime"
    return
  fi
  filtered=$(printf '%s\n' "$current" | filter_acme_cron_entries || true)
  printf '%s\n' "$filtered" | crontab - >/dev/null 2>&1 || return 1
  load_current_crontab || return 1
  if crontab_has_acme_entries "$CURRENT_CRONTAB"; then
    return 1
  fi
  rm -f "$SB_DIR/cert_renew.sh" "$SB_DIR/.cert_mtime"
}

remove_current_acme_cron(){
  local current filtered
  load_current_crontab || return 1
  current=$CURRENT_CRONTAB
  if ! crontab_has_acme_entries "$current"; then
    return 0
  fi
  filtered=$(printf '%s\n' "$current" | filter_acme_cron_entries || true)
  printf '%s\n' "$filtered" | crontab - >/dev/null 2>&1 || return 1
  load_current_crontab || return 1
  ! crontab_has_acme_entries "$CURRENT_CRONTAB"
}

remove_all_managed_crons(){
  local current filtered
  load_current_crontab || return 1
  current=$CURRENT_CRONTAB
  if ! crontab_has_acme_entries "$current" && ! crontab_has_restart_entries "$current"; then
    rm -f "$SB_DIR/cert_renew.sh" "$SB_DIR/.cert_mtime"
    return
  fi
  filtered=$(printf '%s\n' "$current" | filter_acme_cron_entries | filter_restart_cron_entries || true)
  printf '%s\n' "$filtered" | crontab - >/dev/null 2>&1 || return 1
  load_current_crontab || return 1
  if crontab_has_acme_entries "$CURRENT_CRONTAB" || crontab_has_restart_entries "$CURRENT_CRONTAB"; then
    return 1
  fi
  rm -f "$SB_DIR/cert_renew.sh" "$SB_DIR/.cert_mtime"
}

setup_acme_renew_cron(){
  local current filtered entry
  if ! cron_daemon_is_active; then
    red "cron/crond 服务未运行，拒绝写入无法执行的 ACME 续期任务"
    return 1
  fi
  config_uses_acme_certificate || return 1
  [[ -x $ACME_BIN && -f $ACME_HOME/dnsapi/dns_cf.sh && -s $ACME_IDENTITY ]] || return 1
  write_acme_reload_hook || return 1
  load_current_crontab || return 1
  current=$CURRENT_CRONTAB
  filtered=$(printf '%s\n' "$current" | filter_acme_cron_entries || true)
  entry=$(acme_renew_cron_entry)
  { printf '%s\n' "$filtered"; printf '%s\n' "$entry"; } | crontab - >/dev/null 2>&1 || return 1
  load_current_crontab || return 1
  if ! acme_renew_cron_is_current "$CURRENT_CRONTAB"; then
    return 1
  fi
  rm -f "$SB_DIR/cert_renew.sh" "$SB_DIR/.cert_mtime"
}

ensure_acme_renew_cron(){
  local current
  if ! cron_daemon_is_active; then
    red "cron/crond 服务未运行，ACME 自动续期当前不可用"
    return 1
  fi
  load_current_crontab || return 1
  current=$CURRENT_CRONTAB
  if config_uses_acme_certificate; then
    if [[ ! -x $ACME_BIN || ! -f $ACME_HOME/dnsapi/dns_cf.sh || ! -s $ACME_IDENTITY ]]; then
      red "当前配置正在使用 ACME 证书，但续期组件不完整；已保留现有 cron，请立即修复"
      return 1
    fi
    if ! acme_reload_hook_is_current || ! acme_renew_cron_is_current "$current"; then
      setup_acme_renew_cron
    fi
  elif config_uses_self_signed_certificate && { \
       crontab_has_acme_entries "$current"; }; then
    remove_acme_renew_cron
  elif crontab_has_acme_entries "$current"; then
    red "无法确认当前证书模式；为避免中断续期，已保留现有 ACME cron"
    return 1
  fi
}
# sb-module: 70-management
# Certificate management
change_cert_mode(){
  local current_key c_c d_d candidate acme_name menu retry commit_status
  if ! sbactive; then
    readp "按回车返回主菜单..."
    return 1
  fi
  echo
  green "证书管理"
  if ! current_key=$(jq -er '.inbounds[] | select(.type == "hysteria2" and .tag == "hy2-sb") | .tls.key_path' "$SB_CONFIG" 2>/dev/null); then
    red "读取当前证书失败，配置未修改"
    readp "按回车返回主菜单..."
    return 1
  fi

  while true; do
    c_c=
    d_d=
    if [[ $current_key == "$SB_DIR/private.key" ]]; then
      echo "当前证书: 自签bing证书"
      if acme_name=$(detect_acme_identity); then
        while true; do
          green "1：切换为已有 ACME 域名证书 ($acme_name)"
          green "2：通过 Cloudflare 重新申请并切换 ACME 证书"
          yellow "   重新申请会删除旧 ACME 状态，请避免频繁签发"
          green "0：返回主菜单"
          readp "请选择【0-2】：" menu || return 1
          case "$menu" in
            1)
              if cert_acme; then
                c_c="$ACME_CERT"
                d_d="$ACME_KEY"
                break
              fi
              red "已有ACME证书不可用，请重新选择"
              ;;
            2)
              if issue_cloudflare_certificate; then
                c_c="$ACME_CERT"
                d_d="$ACME_KEY"
                break
              fi
              red "ACME证书申请失败，请重新选择"
              ;;
            ""|0) return 0 ;;
            *) red "请输入0、1或2" ;;
          esac
        done
      else
        while true; do
          green "1：通过 Cloudflare 申请并切换 ACME 域名证书"
          green "0：返回主菜单"
          readp "请选择【0-1】：" menu || return 1
          case "$menu" in
            1)
              if issue_cloudflare_certificate; then
                c_c="$ACME_CERT"
                d_d="$ACME_KEY"
                break
              fi
              red "ACME证书申请失败，请重新选择"
              ;;
            ""|0) return 0 ;;
            *) red "请输入0或1" ;;
          esac
        done
      fi
    elif [[ $current_key == "$ACME_KEY" ]]; then
      acme_name=$(detect_acme_identity 2>/dev/null || echo "身份校验失败")
      echo "当前证书: ACME 域名证书 ($acme_name)"
      while true; do
        green "1：切换为自签bing证书"
        green "0：返回主菜单"
        yellow "如需更换域名或 Token，请先切换为自签证书，再进入本菜单重新申请"
        readp "请选择【0-1】：" menu || return 1
        case "$menu" in
          1)
            c_c="$SB_DIR/cert.pem"
            d_d="$SB_DIR/private.key"
            break
            ;;
          ""|0) return 0 ;;
          *) red "请输入0或1" ;;
        esac
      done
    else
      yellow "当前配置使用未知证书路径：$current_key"
      while true; do
        green "1：切换为自签bing证书"
        green "2：申请并切换为 Cloudflare ACME 证书"
        green "0：返回主菜单"
        readp "请选择【0-2】：" menu || return 1
        case "$menu" in
          1)
            c_c="$SB_DIR/cert.pem"
            d_d="$SB_DIR/private.key"
            break
            ;;
          2)
            if issue_cloudflare_certificate; then
              c_c="$ACME_CERT"
              d_d="$ACME_KEY"
              break
            fi
            red "ACME证书申请失败，请重新选择"
            ;;
          ""|0) return 0 ;;
          *) red "请输入0、1或2" ;;
        esac
      done
    fi

    if [[ ! -s $c_c || ! -s $d_d ]]; then
      red "目标证书或私钥不存在，原配置未修改"
      readp "按回车重新选择，输入0返回主菜单：" retry || return 1
      [[ $retry == 0 ]] && return 1
      continue
    fi
    if ! candidate=$(mktemp "$SB_DIR/.sb.json.XXXXXX"); then
      red "创建证书候选配置失败，原配置未修改"
      readp "按回车重试，输入0返回主菜单：" retry || return 1
      [[ $retry == 0 ]] && return 1
      continue
    fi
    if ! jq --arg cert "$c_c" --arg key "$d_d" '
      if ([.inbounds[] | select(.type == "hysteria2" and .tag == "hy2-sb")] | length) != 1
      then error("hy2 inbound missing or duplicated")
      else (.inbounds[] | select(.type == "hysteria2" and .tag == "hy2-sb") | .tls.certificate_path) = $cert |
           (.inbounds[] | select(.type == "hysteria2" and .tag == "hy2-sb") | .tls.key_path) = $key
      end
    ' "$SB_CONFIG" > "$candidate" || \
      ! jq -e --arg cert "$c_c" --arg key "$d_d" '[.inbounds[] | select(.type == "hysteria2" and .tag == "hy2-sb" and .tls.certificate_path == $cert and .tls.key_path == $key)] | length == 1' "$candidate" >/dev/null; then
      rm -f "$candidate"
      red "生成证书候选配置失败，原配置未修改"
      readp "按回车重新选择，输入0返回主菜单：" retry || return 1
      [[ $retry == 0 ]] && return 1
      continue
    fi
    if commit_config "$candidate"; then
      if [[ $d_d == "$ACME_KEY" ]]; then
        setup_acme_renew_cron || yellow "证书已切换，但自动续期任务设置失败，请手动检查 root crontab"
      elif ! remove_acme_renew_cron; then
        yellow "证书已切换，但 ACME 自动续期任务清理失败，请手动检查 root crontab"
      fi
      refresh_share_files_after_change || true
      green "证书模式切换成功"
      readp "按回车返回主菜单..."
      return 0
    else
      commit_status=$?
    fi
    if [[ $commit_status -eq 2 ]]; then
      red "证书切换失败且自动回滚失败，请先检查服务和备份配置"
      readp "按回车返回主菜单..."
      return 2
    fi
    red "证书切换失败，原配置未修改或已恢复"
    readp "按回车重新选择，输入0返回主菜单：" retry || return 1
    [[ $retry == 0 ]] && return 1
  done
}

# Change VL reality SNI
change_vl_sni(){
  local current_sni new_sni candidate retry commit_status
  if ! sbactive; then
    readp "按回车返回主菜单..."
    return 1
  fi
  echo
  if ! current_sni=$(jq -er '.inbounds[] | select(.type == "vless" and .tag == "vless-sb") | .tls.server_name' "$SB_CONFIG" 2>/dev/null); then
    red "读取当前SNI失败，配置未修改"
    readp "按回车返回主菜单..."
    return 1
  fi
  green "当前VL reality SNI域名: $current_sni"
  while true; do
    readp "请输入新的SNI域名 (回车使用apple.com，输入0返回主菜单): " new_sni || return 1
    [[ $new_sni == 0 ]] && return 0
    new_sni=${new_sni:-apple.com}
    if ! valid_hostname "$new_sni"; then
      red "SNI必须是合法域名，例如 apple.com"
      yellow "请重新输入SNI域名"
      continue
    fi
    if ! candidate=$(mktemp "$SB_DIR/.sb.json.XXXXXX"); then
      red "创建SNI候选配置失败，原配置未修改"
      readp "按回车重试，输入0返回主菜单：" retry || return 1
      [[ $retry == 0 ]] && return 1
      continue
    fi
    if ! jq --arg sni "$new_sni" '
      if ([.inbounds[] | select(.type == "vless" and .tag == "vless-sb")] | length) != 1
      then error("vless inbound missing or duplicated")
      else (.inbounds[] | select(.type == "vless" and .tag == "vless-sb") | .tls.server_name) = $sni |
           (.inbounds[] | select(.type == "vless" and .tag == "vless-sb") | .tls.reality.handshake.server) = $sni
      end
    ' "$SB_CONFIG" > "$candidate" || \
      ! jq -e --arg sni "$new_sni" '[.inbounds[] | select(.type == "vless" and .tag == "vless-sb" and .tls.server_name == $sni and .tls.reality.handshake.server == $sni)] | length == 1' "$candidate" >/dev/null; then
      rm -f "$candidate"
      red "生成SNI候选配置失败，原配置未修改"
      readp "按回车重新输入，输入0返回主菜单：" retry || return 1
      [[ $retry == 0 ]] && return 1
      continue
    fi
    if commit_config "$candidate"; then
      refresh_share_files_after_change || true
      green "VL reality SNI域名修改成功：$new_sni"
      readp "按回车返回主菜单..."
      return 0
    fi
    commit_status=$?
    if [[ $commit_status -eq 2 ]]; then
      red "SNI修改失败且自动回滚失败，请先检查服务和备份配置"
      readp "按回车返回主菜单..."
      return 2
    fi
    red "SNI修改失败，原配置未修改或已恢复"
    readp "按回车重新输入，输入0返回主菜单：" retry || return 1
    [[ $retry == 0 ]] && return 1
  done
}

# Change ports
change_ports(){
  local nport port candidate menu retry commit_status vl_port socks_port hy2_port port_vl_re port_socks5 port_hy2
  if ! sbactive; then
    readp "按回车返回主菜单..."
    return 1
  fi
  if ! vl_port=$(jq -er '.inbounds[] | select(.type == "vless" and .tag == "vless-sb") | .listen_port' "$SB_CONFIG" 2>/dev/null) || \
     ! socks_port=$(jq -er '.inbounds[] | select(.type == "socks" and .tag == "socks5-sb") | .listen_port' "$SB_CONFIG" 2>/dev/null) || \
     ! hy2_port=$(jq -er '.inbounds[] | select(.type == "hysteria2" and .tag == "hy2-sb") | .listen_port' "$SB_CONFIG" 2>/dev/null); then
    red "读取当前端口失败，配置未修改"
    readp "按回车返回主菜单..."
    return 1
  fi
  port_vl_re=$vl_port
  port_socks5=$socks_port
  port_hy2=$hy2_port
  echo
  while true; do
    green "更改端口"
    green "1：Vless-reality端口 ${yellow}当前: $vl_port${plain}"
    green "2：Hysteria2主端口 ${yellow}当前: $hy2_port${plain}"
    green "3：SOCKS5端口 ${yellow}当前: $socks_port${plain}"
    green "0：返回主菜单"
    readp "请选择【0-3】：" menu || return 1
    case "$menu" in
      ""|0) return 0 ;;
      1)
        readp "请输入新端口 (1-65535，留空随机10000-65535): " nport || return 1
        port="$nport"
        chooseport tcp "$socks_port" || continue
        if ! candidate=$(mktemp "$SB_DIR/.sb.json.XXXXXX"); then
          red "创建端口候选配置失败，原配置未修改"
          readp "按回车重试，输入0返回主菜单：" retry || return 1
          [[ $retry == 0 ]] && return 1
          continue
        fi
        if ! jq --argjson p "$port" '
          if ([.inbounds[] | select(.type == "vless" and .tag == "vless-sb")] | length) != 1
          then error("vless inbound missing or duplicated")
          else (.inbounds[] | select(.type == "vless" and .tag == "vless-sb") | .listen_port) = $p end
        ' "$SB_CONFIG" > "$candidate" || \
          ! jq -e --argjson p "$port" '[.inbounds[] | select(.type == "vless" and .tag == "vless-sb" and .listen_port == $p)] | length == 1' "$candidate" >/dev/null; then
          rm -f "$candidate"
          red "生成端口候选配置失败，原配置未修改"
          readp "按回车重新输入，输入0返回主菜单：" retry || return 1
          [[ $retry == 0 ]] && return 1
          continue
        fi
        if commit_config "$candidate"; then
          refresh_share_files_after_change || true
          green "Vless-reality端口修改成功：$port"
          yellow "请自行在系统防火墙和VPS厂商安全组放行 ${port}/tcp"
          readp "按回车返回主菜单..."
          return 0
        else
          commit_status=$?
        fi
        if [[ $commit_status -eq 2 ]]; then
          red "端口修改失败且自动回滚失败，请先检查服务和备份配置"
          readp "按回车返回主菜单..."
          return 2
        fi
        red "端口修改失败，原配置未修改或已恢复"
        readp "按回车重新输入，输入0返回主菜单：" retry || return 1
        [[ $retry == 0 ]] && return 1
        ;;
