# sb-module: 80-lifecycle
# Remove an incomplete installation only after its directory ownership has
# been proved. Service and cron cleanup must succeed before data is deleted.
running_from_managed_shortcut(){
  local source_path shortcut_path
  shortcut_is_owned || return 1
  [[ -f $0 && ! -L $0 ]] || return 1
  source_path=$(readlink -f "$0" 2>/dev/null) || return 1
  shortcut_path=$(readlink -f "$SHORTCUT" 2>/dev/null) || return 1
  [[ $source_path == "$shortcut_path" ]]
}

cleanup_incomplete_install(){
  local cleanup_failed=0

  if service_name_conflict; then
    red "检测到不属于本脚本的同名 $SB_SERVICE 服务，拒绝清理安装残留"
    return 1
  fi
  if [[ -e $SB_DIR || -L $SB_DIR ]] && ! managed_directory_is_owned; then
    red "无法确认 $SB_DIR 属于本脚本，已保留该目录"
    return 1
  fi

  if ! cleanup_service; then
    red "停止或移除 sb 服务失败，已保留安装残留以避免误删"
    return 1
  fi
  if command -v crontab >/dev/null 2>&1 && ! remove_all_managed_crons; then
    red "清理 sb 定时任务失败，已保留安装残留以避免误删"
    return 1
  fi

  if managed_directory_is_owned; then
    if ! rm -rf -- "$SB_DIR"; then
      red "删除 $SB_DIR 失败，请检查文件系统权限"
      cleanup_failed=1
    fi
  fi

  if shortcut_is_owned; then
    if running_from_managed_shortcut; then
      yellow "当前正通过 $SHORTCUT 运行，已保留该快捷命令用于继续修复"
    elif ! rm -f -- "$SHORTCUT"; then
      red "删除快捷方式 $SHORTCUT 失败"
      cleanup_failed=1
    fi
  elif [[ -e $SHORTCUT || -L $SHORTCUT ]]; then
    yellow "检测到非本脚本管理的 $SHORTCUT，已保留"
  fi

  return "$cleanup_failed"
}

cleanup_install_transaction(){
  [[ ${INSTALL_TRANSACTION_ACTIVE:-0} -eq 1 ]] || return 0
  INSTALL_TRANSACTION_ACTIVE=0
  cleanup_incomplete_install
}

abort_install_transaction(){
  red "安装未完成，正在清理本次安装产生的文件和服务……"
  if cleanup_install_transaction; then
    green "本次安装残留已清理"
  else
    red "自动清理未完整完成，请检查上方错误后再使用菜单[2]修复"
  fi
  return 1
}

# Uninstall
uninstall(){
  local menu
  if service_name_conflict; then
    red "检测到不属于本脚本的同名 $SB_SERVICE 服务，拒绝执行卸载"
    return 1
  fi
  if [[ -e $SB_DIR || -L $SB_DIR ]] && ! managed_directory_is_owned; then
    red "无法确认 $SB_DIR 属于本脚本，拒绝执行卸载"
    return 1
  fi
  red "确认卸载sb? sb的配置和数据将被删除!"
  yellow "1：确认卸载"
  yellow "0：取消"
  readp "请选择【0-1】：" menu
  if [[ $menu == 1 ]]; then
    if ! cleanup_service; then
      red "停止或移除sb服务失败，卸载已中止；配置与定时任务均保留"
      return 1
    fi
    if ! remove_all_managed_crons; then
      red "服务已停止，但清理sb定时任务失败；配置文件仍保留，可通过菜单[2]修复"
      return 1
    fi
    if ! rm -rf "$SB_DIR"; then
      red "删除sb文件失败，请检查文件系统权限"
      return 1
    fi
    if shortcut_is_owned; then
      if ! rm -f "$SHORTCUT"; then
        red "删除快捷方式 $SHORTCUT 失败，请检查文件系统权限"
        return 1
      fi
    elif [[ -e $SHORTCUT || -L $SHORTCUT ]]; then
      yellow "检测到非本脚本管理的 $SHORTCUT，已保留"
    fi
    green "sb卸载完成！"
    echo
    exit 0
  fi
}
cronsb(){
  local current filtered entry
  if ! cron_daemon_is_active; then
    red "cron/crond 服务未运行，拒绝写入无法执行的每日重启任务"
    return 1
  fi
  load_current_crontab || return 1
  current=$CURRENT_CRONTAB
  filtered=$(printf '%s\n' "$current" | filter_restart_cron_entries || true)
  if command -v apk >/dev/null 2>&1; then
    entry="0 1 * * * rc-service $SB_SERVICE restart > /dev/null 2>&1 $RESTART_CRON_MARKER"
  else
    entry="0 1 * * * systemctl restart $SB_SERVICE > /dev/null 2>&1 $RESTART_CRON_MARKER"
  fi
  { printf '%s\n' "$filtered"; printf '%s\n' "$entry"; } | crontab - >/dev/null 2>&1 || return 1
  load_current_crontab || return 1
  printf '%s\n' "$CURRENT_CRONTAB" | grep -Fq "$RESTART_CRON_MARKER"
}

script_copy_has_identity(){
  local path=$1
  [[ -f $path && ! -L $path ]] || return 1
  grep -Fqx '#!/bin/bash' "$path" 2>/dev/null &&
    grep -Fqx '# sb-generated-artifact: v1' "$path" 2>/dev/null &&
    grep -Fqx 'CORE_VERSION="1.10.7"' "$path" 2>/dev/null &&
    grep -Fqx 'ACME_VERSION="3.1.4"' "$path" 2>/dev/null &&
    grep -Fqx 'SB_DIR="/etc/sb"' "$path" 2>/dev/null &&
    grep -Fqx 'SB_SERVICE="sb"' "$path" 2>/dev/null &&
    grep -Fqx 'SHORTCUT="/usr/bin/sb"' "$path" 2>/dev/null &&
    grep -Eq '^sb_version="v[0-9]+\.[0-9]+\.[0-9]+"$' "$path" 2>/dev/null
}

script_copy_version(){
  local path=$1
  script_copy_has_identity "$path" || return 1
  sed -n 's/^sb_version="v\([0-9][0-9]*\.[0-9][0-9]*\.[0-9][0-9]*\)"$/\1/p' "$path" | head -n 1
}

version_is_older(){
  local candidate=$1 installed=$2
  local c_major c_minor c_patch i_major i_minor i_patch
  IFS=. read -r c_major c_minor c_patch <<< "$candidate"
  IFS=. read -r i_major i_minor i_patch <<< "$installed"
  ((10#$c_major < 10#$i_major)) ||
    ((10#$c_major == 10#$i_major && 10#$c_minor < 10#$i_minor)) ||
    ((10#$c_major == 10#$i_major && 10#$c_minor == 10#$i_minor && 10#$c_patch < 10#$i_patch))
}

shortcut_is_owned(){
  script_copy_has_identity "$SHORTCUT"
}

script_source_is_valid(){
  local path=$1
  script_copy_has_identity "$path"
}

atomic_install_shortcut(){
  local source=$1 mode=$2 shortcut_tmp
  [[ -f $source && ! -L $source && $mode =~ ^[0-7]{3,4}$ ]] || return 1
  shortcut_tmp=$(mktemp "${SHORTCUT}.tmp.XXXXXX") || return 1
  if ! install -m "$mode" "$source" "$shortcut_tmp" || ! mv -f "$shortcut_tmp" "$SHORTCUT"; then
    rm -f "$shortcut_tmp"
    return 1
  fi
}

update_shortcut(){
  local source_path bash_path source_version shortcut_version
  [[ -f $0 && $0 != "/dev/fd/"* && $0 != "bash" ]] || return 1
  source_path=$(readlink -f "$0" 2>/dev/null) || return 1
  bash_path=$(readlink -f "$(command -v bash)" 2>/dev/null || true)
  if [[ -n $bash_path && $source_path == "$bash_path" ]] || ! script_source_is_valid "$source_path"; then
    red "当前运行源不是完整的 sb.sh 文件，拒绝创建快捷方式 $SHORTCUT"
    return 1
  fi
  if [[ $source_path != "$SHORTCUT" ]]; then
    if [[ -e $SHORTCUT || -L $SHORTCUT ]] && ! shortcut_is_owned; then
      red "检测到非本脚本管理的 $SHORTCUT，拒绝覆盖；请先处理该命令冲突"
      return 1
    fi
    if shortcut_is_owned; then
      source_version=$(script_copy_version "$source_path") || return 1
      shortcut_version=$(script_copy_version "$SHORTCUT") || return 1
      if version_is_older "$source_version" "$shortcut_version"; then
        red "当前脚本 v${source_version} 旧于快捷命令 v${shortcut_version}，拒绝降级覆盖"
        return 1
      fi
    fi
    atomic_install_shortcut "$source_path" 755 || return 1
  elif ! shortcut_is_owned; then
    red "$SHORTCUT 归属校验失败，拒绝更新快捷方式"
    return 1
  fi
  return 0
}

prepare_runtime_state(){
  if formal_service_present && ! service_is_owned; then
    red "检测到不属于本脚本的 $SB_SERVICE 服务，拒绝继续"
    return 1
  fi
  prepare_managed_directory
}

cron_daemon_is_active(){
  if command -v apk >/dev/null 2>&1; then
    rc-service crond status >/dev/null 2>&1
  else
    systemctl is-active --quiet cron 2>/dev/null ||
      systemctl is-active --quiet crond 2>/dev/null
  fi
}

enable_cron_daemon(){
  local cron_service
  if command -v apk >/dev/null 2>&1; then
    rc-update add crond default >/dev/null 2>&1 ||
      rc-update show default 2>/dev/null | grep -qE '(^|[[:space:]])crond([[:space:]]|$)' || return 1
    rc-service crond start >/dev/null 2>&1 || cron_daemon_is_active || return 1
  else
    if systemctl cat cron.service >/dev/null 2>&1; then
      cron_service=cron
    elif systemctl cat crond.service >/dev/null 2>&1; then
      cron_service=crond
    else
      return 1
    fi
    systemctl enable --now "$cron_service" >/dev/null 2>&1 || return 1
  fi
  cron_daemon_is_active
}

dependencies_ready(){
  local cmd
  for cmd in bash curl jq openssl ip ss shuf stat tar qrencode crontab install sha256sum; do
    command -v "$cmd" >/dev/null 2>&1 || return 1
  done
  if command -v apk >/dev/null 2>&1; then
    command -v rc-service >/dev/null 2>&1 && command -v rc-update >/dev/null 2>&1 || return 1
  else
    command -v systemctl >/dev/null 2>&1 && [[ -d /run/systemd/system ]] || return 1
  fi
  cron_daemon_is_active
}

install_dependencies(){
  green "安装依赖……"
  if command -v apk >/dev/null 2>&1; then
    apk update && apk add bash jq openssl iproute2 coreutils grep tar tzdata util-linux curl qrencode || return 1
  elif command -v apt-get >/dev/null 2>&1; then
    apt-get update && DEBIAN_FRONTEND=noninteractive apt-get install -y jq cron coreutils util-linux curl openssl iproute2 tar qrencode || return 1
  elif command -v dnf >/dev/null 2>&1; then
    dnf install -y epel-release && dnf install -y jq cronie coreutils util-linux curl openssl iproute tar qrencode || return 1
  elif command -v yum >/dev/null 2>&1; then
    yum install -y epel-release && yum install -y jq cronie coreutils util-linux curl openssl iproute tar qrencode || return 1
  else
    red "未找到受支持的包管理器"
    return 1
  fi
  if ! enable_cron_daemon; then
    red "cron/crond 服务启动失败，无法保证证书自动续期"
    return 1
  fi
  if ! dependencies_ready; then
    red "依赖安装不完整，请检查上方包管理器错误"
    return 1
  fi
  touch "$SB_DIR/.deps_ok"
}
# sb-module: 90-main
# Installation main flow
install_singbox(){
  local key_pair private_key public_key short_id shortcut_ready=0
  if service_name_conflict; then
    red "检测到不属于本脚本的同名 $SB_SERVICE 服务，请先自行处理服务名冲突"
    return 1
  fi
  if is_installed; then
    red "已安装sb，无需重复安装"
    return 1
  fi
  if managed_install_data_present; then
    red "检测到现有或残缺的sb配置数据，拒绝无备份覆盖"
    yellow "请使用菜单[2]修复；残缺安装可在确认后清理并重新安装"
    return 1
  fi
  if [[ -f /etc/systemd/system/sing-box.service || -f /etc/init.d/sing-box || -d /etc/s-box ]]; then
    yellow "检测到旧版或其他 sing-box 安装。sb将使用独立的 $SB_DIR 和 $SB_SERVICE 服务，不会修改旧实例。"
    yellow "请确保两套实例没有使用相同端口。"
    sleep 2
  fi
  if service_exists && ! cleanup_service; then
    red "清理残留的sb服务失败，请先手动检查"
    return 1
  fi
  INSTALL_TRANSACTION_ACTIVE=1
  prepare_managed_directory || { abort_install_transaction; return 1; }
  if [[ ! -f $SB_DIR/.deps_ok ]] || ! dependencies_ready; then
    install_dependencies || { abort_install_transaction; return 1; }
  fi
  v6only
  inssb || { abort_install_transaction; return 1; }
  inscertificate || { abort_install_transaction; return 1; }
  insport || { abort_install_transaction; return 1; }
  sleep 2
  echo
  blue "Vless-reality相关key与id将自动生成……"
  key_pair=$("$SB_BIN" generate reality-keypair 2>/dev/null)
  if [[ -z "$key_pair" ]]; then
    red "生成reality密钥失败，请检查sing-box内核是否正常"
    abort_install_transaction
    return 1
  fi
  private_key=$(echo "$key_pair" | awk '/PrivateKey/ {print $2}' | tr -d '"')
  public_key=$(echo "$key_pair" | awk '/PublicKey/ {print $2}' | tr -d '"')
  if [[ -z $private_key || -z $public_key ]]; then
    red "解析Reality密钥失败"
    abort_install_transaction
    return 1
  fi
  if ! printf '%s\n' "$public_key" > "$SB_DIR/public.key" ||
     ! chmod 600 "$SB_DIR/public.key"; then
    red "保存Reality公钥失败"
    abort_install_transaction
    return 1
  fi
  short_id=$("$SB_BIN" generate rand --hex 4 2>/dev/null)
  if [[ ! $short_id =~ ^[0-9A-Fa-f]{8}$ ]]; then
    red "生成Reality short_id失败"
    abort_install_transaction
    return 1
  fi
  red "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
  green "五、生成配置文件和启动服务"
  inssbjson || { abort_install_transaction; return 1; }
  sbservice || { abort_install_transaction; return 1; }
  if ! sbactive; then
    abort_install_transaction
    return 1
  fi
  yellow "安全提示：SOCKS5本身不加密，仅适合可信链路；脚本已使用独立密码并禁止SOCKS5 UDP"
  yellow "请自行在系统防火墙和VPS厂商安全组放行 ${port_vl_re}/tcp、${port_socks5}/tcp 与 ${port_hy2}/udp"
  if [[ ${use_acme_cert:-0} -eq 1 ]]; then
    setup_acme_renew_cron || yellow "ACME 自动续期任务设置失败，请手动检查 root crontab"
  fi
  if update_shortcut; then
    shortcut_ready=1
  else
    yellow "当前运行方式没有可复制的本地脚本，未创建快捷方式 $SHORTCUT"
  fi
  red "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
  if [[ $shortcut_ready -eq 1 ]]; then
    blue "sb安装成功，Sing-box固定版本 v${CORE_VERSION}，快捷方式: sb"
  else
    blue "sb安装成功，Sing-box固定版本 v${CORE_VERSION}"
  fi
  cronsb || yellow "每日自动重启定时任务设置失败，请手动检查crontab"
  echo
  if ipuuid; then
    sbshare || yellow "节点文件生成失败，请通过菜单[3]重试"
  else
    yellow "公网IP检测失败，服务已启动，但暂未生成分享链接"
  fi
  red "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
  blue "可选择菜单 [3] 刷新并显示所有协议配置及分享链接"
  red "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
  echo
  INSTALL_TRANSACTION_ACTIVE=0
}

repair_singbox(){
  local shortcut_ready=0 repair_choice reinstall_status
  if ! managed_directory_is_owned || ! managed_install_data_present; then
    red "未检测到可修复的sb安装数据"
    readp "按回车返回主菜单..."
    return 1
  fi
  if service_name_conflict; then
    red "检测到不属于sb.sh的同名服务，拒绝修复"
    readp "按回车返回主菜单..."
    return 1
  fi
  if ! installed_config_is_valid; then
    red "现有内核或配置未通过 Sing-box v${CORE_VERSION} 检查，无法直接修复"
    if [[ -x $SB_BIN && -s $SB_CONFIG ]]; then
      "$SB_BIN" check -c "$SB_CONFIG" || true
    fi
    yellow "缺失或损坏的配置无法安全还原；继续会删除本脚本管理的 $SB_DIR 并重新安装"
    yellow "请先备份需要保留的数据"
    yellow "1：清理残缺安装并重新安装"
    yellow "0：取消"
    readp "请选择【0-1】：" repair_choice || return 1
    if [[ $repair_choice != 1 ]]; then
      return 1
    fi
    if ! cleanup_incomplete_install; then
      red "残缺安装清理失败，修复已中止"
      readp "按回车返回主菜单..."
      return 1
    fi
    green "残缺安装已清理，现在重新进入安装流程"
    install_singbox
    reinstall_status=$?
    readp "按回车返回主菜单..."
    return "$reinstall_status"
  fi
  if service_exists; then
    if ! restartsb >/dev/null 2>&1 || ! service_is_active; then
      cleanup_service || {
        red "清理损坏的服务定义失败，修复已中止"
        readp "按回车返回主菜单..."
        return 1
      }
      sbservice || {
        readp "按回车返回主菜单..."
        return 1
      }
    fi
  elif ! sbservice; then
    readp "按回车返回主菜单..."
    return 1
  fi
  if update_shortcut; then
    shortcut_ready=1
  else
    yellow "服务已恢复，但快捷方式 $SHORTCUT 更新失败"
  fi
  ensure_acme_renew_cron || yellow "服务已恢复，但ACME续期状态需要手动检查"
  cronsb || yellow "服务已恢复，但每日重启任务设置失败"
  if [[ $shortcut_ready -eq 1 ]]; then
    green "sb服务修复成功，快捷方式: sb"
  else
    green "sb服务修复成功"
  fi
  readp "按回车返回主菜单..."
}

# Management menu
menu(){
  local Input insV sb_ver status_text status_color
  while true; do
    clear
    white "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
    echo -e "${bblue} ░██     ░██      ░██ ██ ██         ░█${plain}█   ░██     ░██   ░██     ░█${red}█   ░██${plain}  "
    echo -e "${bblue}  ░██   ░██      ░██    ░░██${plain}        ░██  ░██      ░██  ░██${red}      ░██  ░██${plain}   "
    echo -e "${bblue}   ░██ ░██      ░██ ${plain}                ░██ ██        ░██ █${red}█        ░██ ██  ${plain}   "
    echo -e "${bblue}     ░██        ░${plain}██    ░██ ██       ░██ ██        ░█${red}█ ██        ░██ ██  ${plain}  "
    echo -e "${bblue}     ░██ ${plain}        ░██    ░░██        ░██ ░██       ░${red}██ ░██       ░██ ░██ ${plain}  "
    echo -e "${bblue}     ░█${plain}█          ░██ ██ ██         ░██  ░░${red}██     ░██  ░░██     ░██  ░░██ ${plain}  "
    red "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
    insV="$sb_version"
    sb_ver=$([[ -x $SB_BIN ]] && "$SB_BIN" version 2>/dev/null | awk '/version/{print $NF}')
    [[ -z $sb_ver ]] && sb_ver="未安装"
    status_text=$(service_is_active && [[ -s $SB_CONFIG ]] && echo "运行中" || echo "未运行")
    status_color=$([[ "$status_text" = "运行中" ]] && echo "$green" || echo "$yellow")
    echo -e "  版本: ${green}${insV}${plain}  |  Sing-box: ${green}${sb_ver}${plain}  |  状态: ${status_color}${status_text}${plain}"
    v4v6
    [[ -n $v4 ]] && echo -e "  IPV4: ${blue}${v4}${plain}${v4dq:+ (${v4dq})}"
    [[ -n $v6 ]] && echo -e "  IPV6: ${blue}${v6}${plain}${v6dq:+ (${v6dq})}"
    red "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
    green " 1. 安装"
    green " 2. 修复"
    green " 3. 查看节点配置"
    green " 4. 证书管理"
    green " 5. 更改SNI域名"
    green " 6. 更改端口"
    green " 7. 更改协议凭据"
    green " 8. 切换IP优先级"
    green " 9. 卸载"
    green " 0. 退出脚本"
    echo
    readp "请输入数字 [0-9]: " Input || exit 0
    case "$Input" in
      1)
        if is_installed; then
          red "sb已安装，请使用菜单[2]检查或修复服务"
          readp "按回车返回主菜单..."
        elif managed_install_data_present; then
          red "检测到残缺安装，请使用菜单[2]修复"
          readp "按回车返回主菜单..."
        else
          install_singbox
          readp "按回车返回主菜单..."
        fi
        ;;
      2)
        repair_singbox
        ;;
      3)
        if is_installed; then
          sbshare || red "节点配置生成失败，请检查上方错误"
          readp "按回车返回主菜单..."
        else
          red "请先安装 Sing-box"
          sleep 1
        fi
        ;;
      4|5|6|7|8)
        if ! is_installed; then
          red "请先安装或修复 Sing-box"
          sleep 1
        else
          case "$Input" in
            4) change_cert_mode ;;
            5) change_vl_sni ;;
            6) change_ports ;;
            7) change_credentials ;;
            8) switch_ip_priority ;;
          esac
        fi
        ;;
      9)
        if is_installed || service_exists || managed_directory_is_owned || [[ -x $SB_BIN || -s $SB_CONFIG ]]; then
          uninstall
        else
          red "未检测到 sb 安装"
          sleep 1
        fi
        ;;
      0|"") exit 0 ;;
      *) red "请输入正确数字"; sleep 1 ;;
    esac
  done
}

# Make/update shortcut
# sb-entrypoint
prepare_runtime_state || exit 1

handle_install_interrupt(){
  echo
  if [[ ${INSTALL_TRANSACTION_ACTIVE:-0} -eq 1 ]]; then
    abort_install_transaction || true
  fi
  exit 130
}
trap handle_install_interrupt INT TERM HUP

if is_installed; then
  update_shortcut >/dev/null 2>&1 || true
  ensure_acme_renew_cron || yellow "ACME续期自检未通过，请处理上方提示"
fi

# Start
menu
